begin;
update public.empreendimentos set nome='Pinna Studios',cidade='Penha',bairro='Armação do Itapocoroy',endereco='Rua João Francisco Cordeiro, Armação, Penha - SC',tipo='Studio',numero_torres=1,numero_unidades=144,numero_pavimentos=20,total_pavimentos=20,quantidade_unidades=144,area_minima=26.36,area_maxima=35.50,entrega='Set/2031',entrega_date='2031-09-30',data_entrega='set/31',ativo=true,status='ativo',descricao='Pinna Studios, da WG Construtora & Incorporadora, em Armação, Penha/SC. Studios compactos próximos à praia e ao Beto Carrero World, projetados para moradia e locação de curta temporada.',updated_at=now() where id='pinna';
create temporary table tmp_pinna as select * from jsonb_to_recordset(convert_from(decode('','base64'),'UTF8')::jsonb) as r(codigo text,andar int,area numeric,valor numeric,ato numeric,parcela_obra numeric,reforco_obra numeric,parcela_pos numeric,reforco_pos numeric,status_fonte text,status text);
with rows as (select * from tmp_pinna)
update public.unidades u set numero=r.codigo,codigo_unidade=r.codigo,numero_unidade=r.codigo,andar=r.andar,torre='Torre única',area_privativa=r.area,area_interna=r.area,valor_tabela=r.valor,status=r.status,tipologia='Studio',quartos=1,dormitorios=1,vagas=1,entrada_valor=r.ato,entrada_sugerida=r.ato,data_entrega='2031-09-30',data_entrega_unidade='2031-09-30',observacoes=concat('Fonte: tabela Pinna Studios — outubro de 2026. Status da tabela: ',r.status_fonte,'.'),fluxo_dados=jsonb_build_object('versao_padrao',2,'fonte','TabeladeDisponibilidade-PinnaStudios.pdf','data_tabela','2026-10','modalidade','direto_construtora_ate_chaves_financiamento_pos_chaves','entrega','2031-09','percentual_ato',10,'ato',r.ato,'percentual_parcelas_obra',32,'quantidade_parcelas_obra',59,'parcela_obra_valor',r.parcela_obra,'percentual_reforcos_obra',25,'quantidade_reforcos_obra',4,'reforco_obra_valor',r.reforco_obra,'percentual_parcelas_pos_chaves',23,'quantidade_parcelas_pos_chaves',36,'parcela_pos_chaves_valor',r.parcela_pos,'percentual_reforcos_pos_chaves',10,'quantidade_reforcos_pos_chaves',3,'reforco_pos_chaves_valor',r.reforco_pos,'percentual_ate_chaves',67,'percentual_pos_chaves',33,'status_fonte',r.status_fonte,'indice_pre_chaves','CUB','indice_pos_chaves','IPCA','permite_financiamento_bancario',true),updated_at=now() from rows r where u.empreendimento_id='pinna' and u.codigo_unidade=r.codigo;
with rows as (select * from tmp_pinna)
insert into public.unidades(empreendimento_id,numero,codigo_unidade,numero_unidade,torre,andar,area_privativa,area_interna,valor_tabela,status,tipologia,quartos,dormitorios,vagas,entrada_valor,entrada_sugerida,data_entrega,data_entrega_unidade,observacoes,fluxo_dados)
select 'pinna',r.codigo,r.codigo,r.codigo,'Torre única',r.andar,r.area,r.area,r.valor,r.status,'Studio',1,1,1,r.ato,r.ato,'2031-09-30','2031-09-30',concat('Fonte: tabela Pinna Studios — outubro de 2026. Status da tabela: ',r.status_fonte,'.'),jsonb_build_object('versao_padrao',2,'fonte','TabeladeDisponibilidade-PinnaStudios.pdf','data_tabela','2026-10','modalidade','direto_construtora_ate_chaves_financiamento_pos_chaves','entrega','2031-09','percentual_ato',10,'ato',r.ato,'percentual_parcelas_obra',32,'quantidade_parcelas_obra',59,'parcela_obra_valor',r.parcela_obra,'percentual_reforcos_obra',25,'quantidade_reforcos_obra',4,'reforco_obra_valor',r.reforco_obra,'percentual_parcelas_pos_chaves',23,'quantidade_parcelas_pos_chaves',36,'parcela_pos_chaves_valor',r.parcela_pos,'percentual_reforcos_pos_chaves',10,'quantidade_reforcos_pos_chaves',3,'reforco_pos_chaves_valor',r.reforco_pos,'percentual_ate_chaves',67,'percentual_pos_chaves',33,'status_fonte',r.status_fonte,'indice_pre_chaves','CUB','indice_pos_chaves','IPCA','permite_financiamento_bancario',true) from rows r where not exists(select 1 from public.unidades u where u.empreendimento_id='pinna' and u.codigo_unidade=r.codigo);
insert into public.historico_tabelas_preco(empreendimento_id,unidade_id,codigo_unidade,mes_referencia,ano_referencia,data_importacao,valor_tabela,entrada_sugerida,fluxo_dados,observacoes,status_unidade)
select 'pinna',u.id,u.codigo_unidade,10,2026,now(),u.valor_tabela,u.entrada_sugerida,u.fluxo_dados,'Tabela de disponibilidade Pinna Studios — outubro de 2026.',u.status from public.unidades u where u.empreendimento_id='pinna' and not exists(select 1 from public.historico_tabelas_preco h where h.empreendimento_id='pinna' and h.unidade_id=u.id and h.mes_referencia=10 and h.ano_referencia=2026);
commit;